package com.orderflow.delivery.controller;import com.orderflow.delivery.dto.DeliveryResponse;import com.orderflow.delivery.security.RequestIdentity;import com.orderflow.delivery.service.DeliveryQueryService;import java.util.UUID;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/deliveries")public class DeliveryController{private final DeliveryQueryService query;public DeliveryController(DeliveryQueryService q){query=q;}@GetMapping("/orders/{orderId}")public DeliveryResponse order(@PathVariable UUID orderId,JwtAuthenticationToken a){var i=RequestIdentity.from(a.getToken());return query.byOrder(orderId,i.userId(),i.admin());}@GetMapping("/{id}")public DeliveryResponse id(@PathVariable UUID id,JwtAuthenticationToken a){var i=RequestIdentity.from(a.getToken());return query.byId(id,i.userId(),i.admin(),i.deliveryAgent());}}
